// Prepare draft folder paths and generate metadata.json payload
const job = $json;
const pkg = job.ai_package || {};
const ts = new Date().toISOString();

const metadata = {
  internal_job_id: job.internal_job_id,
  prompt_id: job.prompt_id || 'PROMPT_DEFAULT',
  prompt_version: job.prompt_version || 'v3.5',
  style_preset_id: job.style_preset_id || 'BUSINESS_V1',
  generation_revision_version: job.approval_version || 1,
  selected_source_asset_ids: pkg.selected_assets || [],
  generation_timestamp: ts
};

const captionContent = `${pkg.caption || ''}\n\n` +
  `${(pkg.hashtags || []).map(h => h.startsWith('#') ? h : '#' + h).join(' ')}\n\n` +
  `CTA: ${pkg.CTA || ''}`;

const postingInfoContent = `TUDDEH DRAFT POSTING INFO\n` +
  `=========================\n` +
  `Job ID: ${job.internal_job_id}\n` +
  `Business: ${job.business_name}\n` +
  `Format: ${job.content_format}\n` +
  `Headline: ${pkg.headline || ''}\n` +
  `Experience Line: ${pkg.experience_line || ''}\n` +
  `Recommended Date: ${job.recommended_publish_date}\n` +
  `Recommended Time: ${job.recommended_publish_time}\n` +
  `Status: Ready for Review\n` +
  `Timestamp: ${ts}`;

const masterDraftsParentId = $env.DRIVE_04_GENERATED_DRAFTS_FOLDER_ID || '04_GENERATED_DRAFTS_MASTER_ID';
const jobDraftFolderName = `${job.business_name} - ${job.internal_job_id}`;

return [{
  json: {
    ...job,
    metadata_json: metadata,
    caption_txt: captionContent,
    posting_info_txt: postingInfoContent,
    master_drafts_parent_id: masterDraftsParentId,
    job_draft_folder_name: jobDraftFolderName
  }
}];

// Attach created draft folder ID and URL
const prep = $('Prepare Draft Package & Metadata').first().json;
const folder = $input.item.json;
const folderId = folder.id || 'MOCK_DRAFT_FOLDER_ID';
const folderUrl = `https://drive.google.com/drive/folders/${folderId}`;

return [{
  json: {
    ...prep,
    drive_draft_folder_id: folderId,
    draft_folder_url: folderUrl,
    final_asset_link: folderUrl
  }
}];

// Generate unique cryptographic approval token and build signed action URLs (formerly WF-10)
const job = $('Attach Draft Folder ID').first().json;
const pkg = job.ai_package || {};
const crypto = require('crypto');
const token = crypto.randomBytes(24).toString('hex');
const version = Number(job.approval_version || 1);

const webhookBase = ($env.WEBHOOK_TUNNEL_URL || $env.N8N_HOST || 'http://localhost:5678').replace(/\/$/, '');
const approveUrl = `${webhookBase}/webhook/tuddeh-approval?action=approve&jobId=${encodeURIComponent(job.internal_job_id)}&version=${version}&token=${token}`;
const reviseUrl = `${webhookBase}/webhook/tuddeh-approval?action=revise&jobId=${encodeURIComponent(job.internal_job_id)}&version=${version}&token=${token}`;
const rejectUrl = `${webhookBase}/webhook/tuddeh-approval?action=reject&jobId=${encodeURIComponent(job.internal_job_id)}&version=${version}&token=${token}`;

const reviewerEmail = $env.TUDDEH_APPROVAL_EMAIL || 'review@tuddeh.com';

const htmlBody = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0d0f12; color: #f0f0f0; margin: 0; padding: 24px; }
    .container { max-width: 600px; margin: 0 auto; background: #161a22; border-radius: 12px; border: 1px solid #30363d; overflow: hidden; }
    .header { background: #000000; padding: 20px 24px; border-bottom: 2px solid #d4af37; }
    .header h2 { margin: 0; color: #d4af37; font-size: 20px; }
    .badge { display: inline-block; padding: 4px 10px; border-radius: 20px; font-size: 12px; font-weight: 600; background: #21262d; color: #58a6ff; margin-top: 6px; }
    .content { padding: 24px; }
    .section { margin-bottom: 20px; }
    .section-title { font-size: 12px; text-transform: uppercase; letter-spacing: 1px; color: #8b949e; margin-bottom: 6px; }
    .highlight { background: #0d1117; padding: 14px; border-radius: 8px; border-left: 3px solid #d4af37; font-size: 14px; line-height: 1.5; }
    .btn-group { display: flex; gap: 12px; margin-top: 28px; }
    .btn { display: inline-block; padding: 12px 20px; border-radius: 8px; font-weight: 600; text-decoration: none; text-align: center; font-size: 14px; }
    .btn-approve { background: #238636; color: #ffffff; }
    .btn-revise { background: #d29922; color: #ffffff; }
    .btn-reject { background: #da3633; color: #ffffff; }
    .footer { padding: 16px 24px; background: #0d1117; text-align: center; font-size: 12px; color: #8b949e; border-top: 1px solid #21262d; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h2>TUDDEH Approval Required</h2>
      <span class="badge">${job.business_name} • ${job.content_format} (Rev ${version})</span>
    </div>
    <div class="content">
      <div class="section">
        <div class="section-title">Headline & Hook</div>
        <div class="highlight"><strong>${pkg.headline || 'Untitled Hook'}</strong><br><em>${pkg.experience_line || ''}</em></div>
      </div>
      <div class="section">
        <div class="section-title">Caption & CTA</div>
        <div class="highlight" style="white-space: pre-wrap;">${pkg.caption || ''}\n\n${(pkg.hashtags || []).join(' ')}\n\n<strong>CTA:</strong> ${pkg.CTA || ''}</div>
      </div>
      <div class="section">
        <div class="section-title">Recommended Schedule</div>
        <div style="font-size: 14px; color: #c9d1d9;">📅 ${job.recommended_publish_date} at ⏰ ${job.recommended_publish_time}</div>
      </div>
      <div class="section">
        <div class="section-title">Generated Draft Asset</div>
        <div style="margin-top: 8px;">
          <a href="${job.final_asset_link}" target="_blank" style="color: #58a6ff; text-decoration: underline; font-weight: 500;">👉 View Generated Draft in Google Drive</a>
        </div>
      </div>
      <div class="btn-group">
        <a href="${approveUrl}" class="btn btn-approve">✅ Approve</a>
        <a href="${reviseUrl}" class="btn btn-revise">🔄 Request Revision</a>
        <a href="${rejectUrl}" class="btn btn-reject">❌ Reject</a>
      </div>
    </div>
    <div class="footer">
      Job ID: ${job.internal_job_id} • Single-use token secured
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    ...job,
    approval_token: token,
    approval_version: version,
    authorized_reviewer: reviewerEmail,
    email_subject: `[TUDDEH APPROVAL] ${job.business_name} - ${job.marketing_job} (${job.content_format})`,
    email_html: htmlBody
  }
}];
